+        mean_ms: mean(values_s) * 1000.0,
+        median_ms: median_sorted(&sorted) * 1000.0,
+        std_ms: std_dev(values_s) * 1000.0,
+        percentiles_ms: percentiles_from_sorted(&sorted, selected_percentiles),
+    }
